/**
 * FILE: concept_7_wealth_expedition_ship.js
 * THEME: Finance & Investment — Navigating Market Waves & Wealth Expedition Ship
 * STYLE: Modern Flat Vector with Solid Chroma Green Screen (#00FF00)
 * ASPECT RATIO: 16:9 | RESOLUTION READY: FHD / 2K / 4K (Ultra HD)
 * DURATION: 20 Seconds Seamless Loop | SCENES: 1
 * TARGET EXPORT BITRATE: 100 Mbps (Uncompressed Crisp Vector Edges, Zero Glow/Bloom)
 */

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const s = minSide / 1080;
  const cx = width * 0.5;
  const cy = height * 0.5;

  // Fundamental harmonic phases for 100% seamless 20-second loop
  const tau = Math.PI * 2;
  const p1 = sceneProgress * tau + currentScene * 0;
  const p2 = sceneProgress * tau * 2;
  const p3 = sceneProgress * tau * 3;
  const p4 = sceneProgress * tau * 4;

  // Color Palette (Crisp Commercial Flat Vector, Zero Glow)
  const COL = {
    greenScreen: '#00FF00',
    outline: '#162035',
    surfaceWhite: '#FFFFFF',
    surfaceLight: '#F1F5F9',
    surfaceMuted: '#CBD5E1',
    slateDark: '#334155',
    slateMid: '#64748B',
    skyWarmTop: '#FDE68A',
    skyWarmBot: '#BAE6FD',
    seaBack: '#7DD3FC',
    seaMid: '#0284C7',
    seaFront: '#1D4ED8',
    hullDark: '#1E293B',
    hullMid: '#475569',
    sailRed: '#F43F5E',
    sailRedDark: '#E11D48',
    sailWhite: '#FFFFFF',
    goldLight: '#FEF08A',
    goldMid: '#FACC15',
    goldDark: '#EAB308',
    goldDeep: '#CA8A04',
    emeraldLight: '#A7F3D0',
    emeraldMid: '#22C55E',
    emeraldDark: '#15803D',
    cyanMid: '#38BDF8',
    orangeMid: '#FB923C'
  };

  const strokeW = 5.5 * s;
  const thinStrokeW = 3.5 * s;

  ctx.save();
  ctx.shadowBlur = 0;
  ctx.shadowColor = 'transparent';
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';

  // 1. SOLID GREEN SCREEN BACKGROUND
  ctx.fillStyle = COL.greenScreen;
  ctx.fillRect(0, 0, width, height);

  // Helper: Rounded Rectangle Path
  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arcTo(x + w, y, x + w, y + rad, rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arcTo(x + w, y + h, x + w - rad, y + h, rad);
    ctx.lineTo(x + rad, y + h);
    ctx.arcTo(x, y + h, x, y + h - rad, rad);
    ctx.lineTo(x, y + rad);
    ctx.arcTo(x, y, x + rad, y, rad);
    ctx.closePath();
  }

  function fillAndStroke(fillColor, outlineColor, lineWidth) {
    if (fillColor) {
      ctx.fillStyle = fillColor;
      ctx.fill();
    }
    if (outlineColor && lineWidth > 0) {
      ctx.strokeStyle = outlineColor;
      ctx.lineWidth = lineWidth;
      ctx.stroke();
    }
  }

  // Helper: Crisp Vector Dollar Emblem
  function drawVectorDollar(centerX, centerY, scaleSize, color, lineW) {
    const w = 13 * scaleSize;
    const h = 20 * scaleSize;
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = lineW;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    ctx.beginPath();
    ctx.moveTo(centerX + w * 0.75, centerY - h * 0.45);
    ctx.bezierCurveTo(
      centerX + w * 0.75, centerY - h * 0.85,
      centerX - w * 0.85, centerY - h * 0.85,
      centerX - w * 0.85, centerY - h * 0.35
    );
    ctx.bezierCurveTo(
      centerX - w * 0.85, centerY + h * 0.02,
      centerX + w * 0.85, centerY - h * 0.02,
      centerX + w * 0.85, centerY + h * 0.40
    );
    ctx.bezierCurveTo(
      centerX + w * 0.85, centerY + h * 0.85,
      centerX - w * 0.75, centerY + h * 0.85,
      centerX - w * 0.75, centerY + h * 0.45
    );
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(centerX, centerY - h * 0.98);
    ctx.lineTo(centerX, centerY + h * 0.98);
    ctx.stroke();
    ctx.restore();
  }

  // Helper: Crisp Vector Upward Arrow
  function drawUpArrow(centerX, centerY, size, color, lineW) {
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = lineW;
    ctx.beginPath();
    ctx.moveTo(centerX, centerY + size * 0.7);
    ctx.lineTo(centerX, centerY - size * 0.65);
    ctx.moveTo(centerX - size * 0.55, centerY - size * 0.1);
    ctx.lineTo(centerX, centerY - size * 0.7);
    ctx.lineTo(centerX + size * 0.55, centerY - size * 0.1);
    ctx.stroke();
    ctx.restore();
  }

  // Helper: Crisp Gold Coin Medallion
  function drawGoldMedallion(centerX, centerY, radius, dollarScale) {
    ctx.beginPath();
    ctx.arc(centerX, centerY, radius, 0, tau);
    fillAndStroke(COL.goldMid, COL.outline, thinStrokeW);

    ctx.beginPath();
    ctx.arc(centerX, centerY, radius * 0.74, 0, tau);
    fillAndStroke(COL.goldLight, COL.outline, 2.5 * s);

    drawVectorDollar(centerX, centerY, dollarScale, COL.outline, 3.2 * s);
  }

  // Helper: Side-View Stacked Coin Cylinder
  function drawCoinCylinder(centerX, topY, coinW, coinH) {
    roundedRectPath(centerX - coinW * 0.5, topY, coinW, coinH, 7 * s);
    fillAndStroke(COL.goldMid, COL.outline, thinStrokeW);

    roundedRectPath(centerX - coinW * 0.40, topY + 4 * s, coinW * 0.20, coinH - 8 * s, 3.5 * s);
    fillAndStroke(COL.goldLight, null, 0);

    roundedRectPath(centerX + coinW * 0.20, topY + 4 * s, coinW * 0.20, coinH - 8 * s, 3.5 * s);
    fillAndStroke(COL.goldDeep, null, 0);

    roundedRectPath(centerX - coinW * 0.5, topY, coinW, coinH, 7 * s);
    fillAndStroke(null, COL.outline, thinStrokeW);
  }

  // Helper: 4-Point Guiding Star Vector
  function drawGuidingStar(centerX, centerY, outerR, innerR, fillCol) {
    ctx.beginPath();
    for (let i = 0; i < 8; i++) {
      const ang = (i * Math.PI) / 4;
      const r = i % 2 === 0 ? outerR : innerR;
      const sx = centerX + Math.cos(ang) * r;
      const sy = centerY + Math.sin(ang) * r;
      if (i === 0) ctx.moveTo(sx, sy);
      else ctx.lineTo(sx, sy);
    }
    ctx.closePath();
    fillAndStroke(fillCol, COL.outline, 2.5 * s);
  }

  // =========================================================================
  // 2. STRUCTURAL BASELINE PLATFORM & NON-INTERSECTING NAVIGATION BRIDGES
  // =========================================================================
  const baseLineY = cy + 395 * s;

  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = strokeW;
  ctx.beginPath();
  ctx.moveTo(cx - 735 * s, baseLineY);
  ctx.lineTo(cx + 735 * s, baseLineY);
  ctx.stroke();

  // Outer baseline accent ticks
  const tickShift = Math.sin(p2) * 6 * s;
  ctx.beginPath();
  ctx.moveTo(cx - 810 * s - tickShift, baseLineY);
  ctx.lineTo(cx - 760 * s - tickShift, baseLineY);
  ctx.moveTo(cx + 760 * s + tickShift, baseLineY);
  ctx.lineTo(cx + 810 * s + tickShift, baseLineY);
  ctx.stroke();

  // Sub-platform line
  ctx.beginPath();
  ctx.moveTo(cx - 360 * s, baseLineY + 18 * s);
  ctx.lineTo(cx + 360 * s, baseLineY + 18 * s);
  ctx.stroke();

  // Dedicated Horizontal Navigation Bridges in Lower Corridor (y = cy + 205*s)
  // Left gap: [cx - 285*s, cx - 228*s] | Right gap: [cx + 228*s, cx + 285*s]
  const bridgeY = cy + 205 * s;
  ctx.strokeStyle = COL.outline;
  ctx.lineWidth = thinStrokeW;
  ctx.beginPath();
  ctx.moveTo(cx - 282 * s, bridgeY);
  ctx.lineTo(cx - 230 * s, bridgeY);
  ctx.moveTo(cx + 230 * s, bridgeY);
  ctx.lineTo(cx + 282 * s, bridgeY);
  ctx.stroke();

  const bProgL = (sceneProgress * 4) % 1;
  ctx.beginPath();
  ctx.arc(cx - 276 * s + bProgL * 40 * s, bridgeY, 6 * s, 0, tau);
  fillAndStroke(COL.cyanMid, COL.outline, 2.5 * s);

  const bProgR = (sceneProgress * 4 + 0.5) % 1;
  ctx.beginPath();
  ctx.arc(cx + 236 * s + bProgR * 40 * s, bridgeY, 6 * s, 0, tau);
  fillAndStroke(COL.goldMid, COL.outline, 2.5 * s);

  // =========================================================================
  // 3. LEFT-TOP ZONE: FINANCIAL NAVIGATION COMPASS & DIRECTIONAL ROSE CARD
  // Bounding Box: x in [cx - 685*s, cx - 295*s], y in [cy - 360*s, cy - 35*s]
  // =========================================================================
  const ltFloatY = Math.sin(p2) * 4.5 * s;
  const ltX = cx - 685 * s;
  const ltY = cy - 360 * s + ltFloatY;
  const ltW = 390 * s;
  const ltH = 315 * s;

  roundedRectPath(ltX, ltY, ltW, ltH, 20 * s);
  fillAndStroke(COL.surfaceWhite, COL.outline, strokeW);

  // Top Header Strip inside Left-Top Card
  roundedRectPath(ltX + 18 * s, ltY + 18 * s, ltW - 36 * s, 46 * s, 12 * s);
  fillAndStroke(COL.surfaceLight, COL.outline, thinStrokeW);

  // 3 Navigation Status Dots
  const navDots = [COL.cyanMid, COL.goldMid, COL.emeraldMid];
  for (let d = 0; d < 3; d++) {
    ctx.beginPath();
    ctx.arc(ltX + 40 * s + d * 24 * s, ltY + 41 * s, 7 * s, 0, tau);
    fillAndStroke(navDots[d], COL.outline, 2.5 * s);
  }

  roundedRectPath(ltX + 118 * s, ltY + 35 * s, 150 * s, 12 * s, 6 * s);
  fillAndStroke(COL.slateDark, null, 0);

  roundedRectPath(ltX + ltW - 102 * s, ltY + 27 * s, 68 * s, 28 * s, 8 * s);
  fillAndStroke(COL.emeraldMid, COL.outline, 2.5 * s);

  // Left Sub-Box inside Card: Precision Financial Compass Dial
  const compCX = ltX + 112 * s;
  const compCY = ltY + 188 * s;
  const compOuterR = 84 * s;
  const compInnerR = 68 * s;

  // Outer Compass Bezel
  ctx.beginPath();
  ctx.arc(compCX, compCY, compOuterR, 0, tau);
  fillAndStroke(COL.goldMid, COL.outline, strokeW);

  // Inner Compass Face
  ctx.beginPath();
  ctx.arc(compCX, compCY, compInnerR, 0, tau);
  fillAndStroke(COL.surfaceLight, COL.outline, thinStrokeW);

  // 8 Cardinal & Intercardinal Tick Marks inside Compass Face
  for (let k = 0; k < 8; k++) {
    const ka = (k * tau) / 8;
    const isCard = k % 2 === 0;
    const rIn = compInnerR - (isCard ? 16 : 10) * s;
    const rOut = compInnerR - 4 * s;
    ctx.strokeStyle = COL.outline;
    ctx.lineWidth = (isCard ? 4 : 2.5) * s;
    ctx.beginPath();
    ctx.moveTo(compCX + Math.cos(ka) * rIn, compCY + Math.sin(ka) * rIn);
    ctx.lineTo(compCX + Math.cos(ka) * rOut, compCY + Math.sin(ka) * rOut);
    ctx.stroke();
  }

  // Animated Compass Needle pointing toward North-East Profit Bearing (-0.65 rad + smooth oscillation)
  const bearingAngle = -0.65 + Math.sin(p2) * 0.16;
  ctx.save();
  ctx.translate(compCX, compCY);
  ctx.rotate(bearingAngle);

  // North/Profit Half of Needle (Vibrant Coral-Red)
  ctx.beginPath();
  ctx.moveTo(0, -11 * s);
  ctx.lineTo(50 * s, 0);
  ctx.lineTo(0, 11 * s);
  ctx.closePath();
  fillAndStroke(COL.sailRed, COL.outline, 3 * s);

  // South Half of Needle (Slate Dark)
  ctx.beginPath();
  ctx.moveTo(0, -11 * s);
  ctx.lineTo(-50 * s, 0);
  ctx.lineTo(0, 11 * s);
  ctx.closePath();
  fillAndStroke(COL.slateDark, COL.outline, 3 * s);

  // Center Compass Pin
  ctx.beginPath();
  ctx.arc(0, 0, 10 * s, 0, tau);
  fillAndStroke(COL.goldMid, COL.outline, 2.8 * s);
  ctx.restore();

  // Right Sub-Box inside Card: 3 Directional Telemetry Readouts (Strictly separated from Compass)
  const navBarX = ltX + 216 * s;
  const navBarW = 152 * s;
  for (let r = 0; r < 3; r++) {
    const ry = ltY + 104 * s + r * 62 * s;
    roundedRectPath(navBarX, ry, navBarW, 46 * s, 10 * s);
    fillAndStroke(COL.surfaceLight, COL.outline, 2.8 * s);

    // Status pill & animated bearing meter
    roundedRectPath(navBarX + 12 * s, ry + 10 * s, 56 * s, 8 * s, 4 * s);
    fillAndStroke(COL.slateDark, null, 0);

    roundedRectPath(navBarX + 12 * s, ry + 24 * s, navBarW - 24 * s, 12 * s, 6 * s);
    fillAndStroke(COL.surfaceWhite, COL.outline, 2 * s);

    const fillW = (0.55 + 0.30 * Math.sin(p2 + r * 1.1)) * (navBarW - 28 * s);
    roundedRectPath(navBarX + 14 * s, ry + 26 * s, fillW, 8 * s, 4 * s);
    fillAndStroke(navDots[r], null, 0);
  }

  // =========================================================================
  // 4. LEFT-BOTTOM ZONE: GLOBAL TRADE ROUTE ALLOCATION & GOLD RESERVES
  // Bounding Box: x in [cx - 685*s, cx - 295*s], y in [cy + 25*s, cy + 395*s]
  // =========================================================================
  const lbFloatY = Math.cos(p2) * 4 * s;
  const lbX = cx - 685 * s;
  const lbY = cy + 25 * s + lbFloatY;
  const lbW = 390 * s;
  const lbCardH = 190 * s;

  // 4A. Upper Portfolio Route Allocation Card
  roundedRectPath(lbX, lbY, lbW, lbCardH, 20 * s);
  fillAndStroke(COL.surfaceWhite, COL.outline, strokeW);

  // Left Segmented Donut Ring inside Card
  const dCX = lbX + 80 * s;
  const dCY = lbY + lbCardH * 0.5;
  const dR = 52 * s;
  const dAngles = [0, tau * 0.44, tau * 0.76, tau];
  const dCols = [COL.seaMid, COL.emeraldMid, COL.goldMid];

  for (let k = 0; k < 3; k++) {
    ctx.beginPath();
    ctx.moveTo(dCX, dCY);
    ctx.arc(dCX, dCY, dR, p1 + dAngles[k], p1 + dAngles[k + 1]);
    ctx.closePath();
    fillAndStroke(dCols[k], COL.outline, thinStrokeW);
  }
  ctx.beginPath();
  ctx.arc(dCX, dCY, 24 * s, 0, tau);
  fillAndStroke(COL.surfaceWhite, COL.outline, thinStrokeW);

  // Right 3 Progress Meters
  const mStartX = lbX + 156 * s;
  const mWidth = 210 * s;
  for (let m = 0; m < 3; m++) {
    const my = lbY + 34 * s + m * 48 * s;
    roundedRectPath(mStartX, my, 84 * s, 9 * s, 4.5 * s);
    fillAndStroke(COL.slateMid, null, 0);

    roundedRectPath(mStartX, my + 15 * s, mWidth, 18 * s, 9 * s);
    fillAndStroke(COL.surfaceLight, COL.outline, 2.5 * s);

    const mFill = (0.58 + 0.26 * Math.sin(p2 + m * 1.2)) * (mWidth - 6 * s);
    roundedRectPath(mStartX + 3 * s, my + 18 * s, mFill, 12 * s, 6 * s);
    fillAndStroke(dCols[m], null, 0);
  }

  // 4B. Lower Gold Bullion & Coin Pedestal on baseLineY
  const pedLX = lbX;
  const pedLW = lbW;
  const pedLH = 24 * s;
  const pedLY = baseLineY - pedLH;

  roundedRectPath(pedLX, pedLY, pedLW, pedLH, 8 * s);
  fillAndStroke(COL.slateDark, COL.outline, strokeW);

  function drawBullionBar(centerX, bottomY, barW, barH) {
    const topW = barW * 0.78;
    ctx.beginPath();
    ctx.moveTo(centerX - barW * 0.5, bottomY);
    ctx.lineTo(centerX - topW * 0.5, bottomY - barH);
    ctx.lineTo(centerX + topW * 0.5, bottomY - barH);
    ctx.lineTo(centerX + barW * 0.5, bottomY);
    ctx.closePath();
    fillAndStroke(COL.goldMid, COL.outline, thinStrokeW);

    ctx.beginPath();
    ctx.moveTo(centerX - topW * 0.38, bottomY - barH + 7 * s);
    ctx.lineTo(centerX + topW * 0.38, bottomY - barH + 7 * s);
    ctx.lineTo(centerX + topW * 0.42, bottomY - 7 * s);
    ctx.lineTo(centerX - topW * 0.42, bottomY - 7 * s);
    ctx.closePath();
    fillAndStroke(COL.goldLight, null, 0);
  }

  // Column 1 (Left): 2 Stacked Gold Bullion Bars (x center = lbX + 84*s, spans [22, 146])
  const bulCX = lbX + 84 * s;
  drawBullionBar(bulCX, pedLY, 124 * s, 38 * s);
  drawBullionBar(bulCX, pedLY - 38 * s, 108 * s, 36 * s);

  // Column 2 (Middle): 4 Stacked Gold Coins (x center = lbX + 216*s, spans [174, 258], 28*s clear gap!)
  const stackLCX = lbX + 216 * s;
  const cH = 24 * s;
  for (let c = 0; c < 4; c++) {
    drawCoinCylinder(stackLCX, pedLY - (c + 1) * cH, 84 * s, cH);
  }

  // Column 3 (Right): Front Gold Dollar Medallion on Stand (x center = lbX + 330*s, spans [286, 374], 28*s clear gap!)
  const medLCX = lbX + 330 * s;
  const medLCY = pedLY - 64 * s + Math.sin(p2) * 4 * s;
  roundedRectPath(medLCX - 22 * s, pedLY - 16 * s, 44 * s, 16 * s, 5 * s);
  fillAndStroke(COL.goldDeep, COL.outline, thinStrokeW);
  drawGoldMedallion(medLCX, medLCY, 44 * s, 1.25 * s);

  // =========================================================================
  // 5. CENTER ZONE: NAUTICAL PORTHOLE EMBLEM, WEALTH SHIP & MARKET WAVES
  // Directly inspired by the sailboat on layered blue waves in reference video (01:09 - 01:17)
  // Porthole Center: (cx, cy - 18*s), Outer Radius: 215*s
  // =========================================================================
  const portCX = cx;
  const portCY = cy - 18 * s + Math.sin(p1) * 4 * s;
  const outerPortR = 215 * s;
  const innerPortR = 186 * s;

  // 5A. Central Porthole Pedestal Stand on baseLineY (y: cy + 318*s to cy + 395*s)
  // Upper cradle supporting the porthole ring
  roundedRectPath(cx - 88 * s, cy + 312 * s, 176 * s, 46 * s, 10 * s);
  fillAndStroke(COL.slateMid, COL.outline, strokeW);

  // Lower wide pedestal base sitting flush on baseLineY
  roundedRectPath(cx - 148 * s, baseLineY - 40 * s, 296 * s, 40 * s, 12 * s);
  fillAndStroke(COL.slateDark, COL.outline, strokeW);

  roundedRectPath(cx - 104 * s, baseLineY - 24 * s, 208 * s, 10 * s, 5 * s);
  fillAndStroke(COL.goldMid, null, 0);

  // 5B. Outer Golden-Brass Nautical Porthole Frame & 8 Perimeter Rivet Bolts
  ctx.beginPath();
  ctx.arc(portCX, portCY, outerPortR, 0, tau);
  fillAndStroke(COL.goldMid, COL.outline, strokeW);

  // 8 Non-Overlapping Rivet Bolts around Porthole Frame
  const boltMidR = (outerPortR + innerPortR) * 0.5;
  for (let b = 0; b < 8; b++) {
    const ba = (b * tau) / 8 + Math.PI / 8;
    const bx = portCX + Math.cos(ba) * boltMidR;
    const by = portCY + Math.sin(ba) * boltMidR;
    ctx.beginPath();
    ctx.arc(bx, by, 6 * s, 0, tau);
    fillAndStroke(COL.surfaceWhite, COL.outline, 2.5 * s);
  }

  // 5C. Clipped Porthole Scene: Golden Sky, Guiding Stars, Wealth Ship & 3 Wave Layers
  ctx.save();
  ctx.beginPath();
  ctx.arc(portCX, portCY, innerPortR, 0, tau);
  ctx.clip();

  // Warm Golden-Horizon Sky Gradient (Matches reference video 01:10 warm sky)
  const skyGrad = ctx.createLinearGradient(0, portCY - innerPortR, 0, portCY + innerPortR * 0.4);
  skyGrad.addColorStop(0.0, COL.skyWarmTop);
  skyGrad.addColorStop(1.0, COL.skyWarmBot);
  ctx.fillStyle = skyGrad;
  ctx.fillRect(portCX - innerPortR, portCY - innerPortR, innerPortR * 2, innerPortR * 2);

  // Guiding Stars & Golden Horizon Disc in Upper Sky (Strictly separated from sails)
  // Sun disc on upper-left of sky
  const skySunX = portCX - 106 * s;
  const skySunY = portCY - 96 * s + Math.cos(p2) * 3 * s;
  ctx.beginPath();
  ctx.arc(skySunX, skySunY, 24 * s, 0, tau);
  fillAndStroke(COL.goldLight, COL.outline, 3 * s);

  // Two 4-Point Guiding Stars in upper sky
  const starScale1 = 0.88 + 0.12 * Math.sin(p4);
  drawGuidingStar(portCX - 62 * s, portCY - 138 * s, 13 * s * starScale1, 5 * s * starScale1, COL.surfaceWhite);

  const starScale2 = 0.88 + 0.12 * Math.cos(p4);
  drawGuidingStar(portCX + 112 * s, portCY - 108 * s, 14 * s * starScale2, 5.5 * s * starScale2, COL.goldMid);

  // Helper: Draw a Single Ocean Wave Layer inside Porthole
  function drawOceanWaveLayer(baseY, amp, wavelength, phase, fillColor, outlineColor, lineW) {
    const leftX = portCX - innerPortR - 20 * s;
    const rightX = portCX + innerPortR + 20 * s;
    const steps = 36;
    const span = rightX - leftX;

    ctx.beginPath();
    ctx.moveTo(leftX, portCY + innerPortR + 20 * s);
    for (let i = 0; i <= steps; i++) {
      const u = i / steps;
      const wx = leftX + u * span;
      const wy = baseY + Math.sin(((wx - portCX) / wavelength) * tau + phase) * amp;
      ctx.lineTo(wx, wy);
    }
    ctx.lineTo(rightX, portCY + innerPortR + 20 * s);
    ctx.closePath();
    ctx.fillStyle = fillColor;
    ctx.fill();

    if (outlineColor && lineW > 0) {
      ctx.beginPath();
      for (let i = 0; i <= steps; i++) {
        const u = i / steps;
        const wx = leftX + u * span;
        const wy = baseY + Math.sin(((wx - portCX) / wavelength) * tau + phase) * amp;
        if (i === 0) ctx.moveTo(wx, wy);
        else ctx.lineTo(wx, wy);
      }
      ctx.strokeStyle = outlineColor;
      ctx.lineWidth = lineW;
      ctx.stroke();
    }
  }

  // Wave Layer 1 (Back Horizon Swells - Light Blue)
  const wave1Y = portCY + 34 * s;
  drawOceanWaveLayer(wave1Y, 9 * s, 190 * s, -p2 + 0.6, COL.seaBack, COL.outline, 3 * s);

  // Wave Layer 2 (Mid Ocean Wave supporting the Ship - Medium Blue)
  const wave2Y = portCY + 52 * s;
  const wave2Amp = 11 * s;
  const wave2Len = 220 * s;
  drawOceanWaveLayer(wave2Y, wave2Amp, wave2Len, p2, COL.seaMid, COL.outline, 3.5 * s);

  // 5D. Wealth Expedition Ship (Buoyantly riding Wave Layer 2, behind Foreground Wave Layer 3)
  // Calculate exact buoyancy height & pitch derivative from Wave Layer 2 at x = portCX
  const shipHeave = Math.sin(p2) * wave2Amp * 0.75;
